import React, { useState, useEffect } from 'react';
import api from '../api';

const InteractiveSeating = ({ event, user, onBack, onCheckoutSuccess, showToast }) => {
    const [seats, setSeats] = useState([]);
    const [secondsLeft, setSecondsLeft] = useState(0);
    const [paymentMethod, setPaymentMethod] = useState('apple');

    const fetchSeats = async () => {
        try {
            const res = await api.get(`/events/${event.id}/seats`);
            setSeats(res.data);
        } catch (err) {
            showToast('Failed to load seating chart', 'error');
        }
    };

    useEffect(() => {
        fetchSeats();
    }, [event.id]);

    const myLockedSeats = seats.filter(s => s.status === 'LOCKED' && s.lockedByUserId === user.id);

    useEffect(() => {
        if (myLockedSeats.length === 0) {
            setSecondsLeft(0);
            return;
        }
        setSecondsLeft(300);
        const timer = setInterval(() => {
            setSecondsLeft(prev => {
                if (prev <= 1) {
                    clearInterval(timer);
                    fetchSeats();
                    showToast('Temporary seat lock expired (05:00).', 'warning');
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
        return () => clearInterval(timer);
    }, [myLockedSeats.length]);

    const handleSeatClick = async (seat) => {
        if (seat.status === 'SOLD') return;
        if (seat.status === 'LOCKED' && seat.lockedByUserId !== user.id) {
            showToast('Seat is currently reserved by another guest.', 'warning');
            return;
        }
        if (seat.status === 'AVAILABLE' && myLockedSeats.length >= 6) {
            showToast('Maximum 6 seats per reservation.', 'warning');
            return;
        }
        try {
            await api.post(`/seats/${seat.id}/toggle-lock`);
            await fetchSeats();
        } catch (err) {
            showToast(err.response?.data?.message || 'Seat unavailable', 'error');
            fetchSeats();
        }
    };

    const handleCheckout = async () => {
        try {
            const seatIds = myLockedSeats.map(s => s.id);
            const res = await api.post('/orders/checkout', { eventId: event.id, seatIds, paymentMethod });
            showToast(`Added ${res.data.issuedCount} pass(es) to your Wallet.`, 'success');
            onCheckoutSuccess();
        } catch (err) {
            showToast(err.response?.data?.message || 'Checkout failed', 'error');
        }
    };

    const rows = ['A', 'B', 'C', 'D', 'E', 'F'];
    const totalAmount = myLockedSeats.reduce((sum, s) => sum + s.price, 0);
    const mins = String(Math.floor(secondsLeft / 60)).padStart(2, '0');
    const secs = String(secondsLeft % 60).padStart(2, '0');

    return (
        <div className="space-y-6">
            {/* Top Spatial Header Bar */}
            <div className="flex flex-wrap items-center justify-between gap-4 liquid-glass rounded-[28px] p-4 sm:p-5">
                <div className="flex items-center gap-3.5">
                    <button onClick={onBack} className="w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 border border-white/20 flex items-center justify-center text-white transition">
                        ←
                    </button>
                    <div>
                        <div className="flex items-center gap-2.5">
                            <h2 className="text-lg sm:text-xl font-bold tracking-tight text-white">{event.title}</h2>
                            <span className="text-[11px] font-semibold px-3 py-0.5 rounded-full bg-white/15 text-white/90 border border-white/20">{event.category}</span>
                        </div>
                        <p className="text-xs sm:text-sm text-white/60">{event.venue} • {event.date}</p>
                    </div>
                </div>

                {myLockedSeats.length > 0 && (
                    <div className="flex items-center gap-3 px-4 py-2 rounded-full bg-amber-400/15 border border-amber-300/35 backdrop-blur-md">
                        <span className="w-2.5 h-2.5 rounded-full bg-amber-300 animate-ping"></span>
                        <div>
                            <p className="text-[10px] uppercase tracking-widest font-semibold text-amber-200/80">Seat Hold Timer</p>
                            <p className="font-mono text-base font-bold text-amber-300 leading-none">{mins}:{secs}</p>
                        </div>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Left: Spatial Auditorium Map */}
                <div className="lg:col-span-2 liquid-glass rounded-[30px] p-6 sm:p-7 flex flex-col justify-between">
                    <div>
                        <div className="flex flex-wrap items-center justify-between gap-2 mb-5">
                            <h3 className="font-semibold text-white">Spatial Seat Selection</h3>
                            <div className="flex flex-wrap items-center gap-3 text-xs text-white/75">
                                <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded-full bg-amber-300/80 border border-white/40 inline-block"></span> VIP</span>
                                <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded-full bg-sky-400/80 border border-white/40 inline-block"></span> Golden</span>
                                <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded-full bg-white/20 border border-white/30 inline-block"></span> General</span>
                                <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded-full bg-emerald-400 border border-white inline-block"></span> Selected</span>
                            </div>
                        </div>

                        {/* Curved VisionOS Stage Horizon */}
                        <div className="my-5">
                            <div className="w-4/5 mx-auto h-11 rounded-t-full bg-gradient-to-b from-white/25 to-transparent border-t-2 border-white/60 flex items-center justify-center shadow-[0_-12px_30px_rgba(255,255,255,0.15)]">
                                <span className="text-[11px] font-mono font-semibold tracking-[0.3em] text-white/80 uppercase">STAGE HORIZON</span>
                            </div>
                        </div>

                        <div className="space-y-2.5 max-w-xl mx-auto py-3 overflow-x-auto">
                            {rows.map(rowChar => {
                                const rowSeats = seats.filter(s => s.seatIdentifier.startsWith(rowChar));
                                if (rowSeats.length === 0) return null;
                                return (
                                    <div key={rowChar} className="flex items-center justify-center gap-2.5">
                                        <span className="w-6 text-xs font-mono font-semibold text-white/40 text-right">{rowChar}</span>
                                        <div className="flex items-center gap-2">
                                            {rowSeats.map((s, idx) => {
                                                const isMine = s.status === 'LOCKED' && s.lockedByUserId === user.id;
                                                const isUnavailable = s.status === 'SOLD' || (s.status === 'LOCKED' && !isMine);
                                                const aisle = idx === 3 ? 'mr-5' : '';

                                                let btnStyle = 'bg-white/10 border-white/20 text-white hover:bg-white/25';
                                                if (s.tier.includes('VIP')) btnStyle = 'bg-amber-300/25 border-amber-200/50 text-amber-100 hover:bg-amber-300/40';
                                                else if (s.tier.includes('Golden')) btnStyle = 'bg-sky-400/25 border-sky-300/50 text-sky-100 hover:bg-sky-400/40';

                                                if (isMine) btnStyle = 'bg-emerald-400 border-white text-slate-950 font-extrabold scale-110 shadow-[0_0_20px_rgba(52,211,153,0.6)]';
                                                if (isUnavailable) btnStyle = 'bg-white/[0.03] border-white/5 text-white/20 cursor-not-allowed';

                                                return (
                                                    <button key={s.id} disabled={isUnavailable} onClick={() => handleSeatClick(s)} className={`w-9 h-9 rounded-xl border backdrop-blur-md font-mono font-semibold text-xs transition-all duration-200 ${btnStyle} ${aisle}`}>
                                                        {s.seatIdentifier}
                                                    </button>
                                                );
                                            })}
                                        </div>
                                        <span className="w-20 text-[11px] font-mono text-white/50 pl-2">{rowSeats[0]?.price} RON</span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>

                    <div className="mt-5 pt-3.5 border-t border-white/10 flex items-center justify-between text-[11px] text-white/45 font-mono">
                        <span>Atomic Lock: InnoDB Row-Level</span>
                        <span>Pass Type: Apple Wallet NFC / QR</span>
                    </div>
                </div>

                {/* Right: Frosted Checkout Sheet */}
                <div className="liquid-glass rounded-[30px] p-6 flex flex-col justify-between space-y-5">
                    <div className="space-y-4">
                        <h3 className="font-bold text-lg text-white border-b border-white/10 pb-3">Pass Summary</h3>
                        <div className="space-y-2.5 max-h-60 overflow-y-auto pr-1">
                            {myLockedSeats.length === 0 ? (
                                <p className="text-sm text-white/45 py-8 text-center">Tap seats on the spatial map to reserve them.</p>
                            ) : (
                                myLockedSeats.map(s => (
                                    <div key={s.id} className="flex items-center justify-between liquid-well rounded-2xl px-4 py-3">
                                        <div>
                                            <p className="text-xs font-bold text-white">Seat {s.seatIdentifier} <span className="text-white/60 font-normal">• {s.tier}</span></p>
                                            <p className="text-[11px] font-mono text-emerald-300">Reserved</p>
                                        </div>
                                        <div className="flex items-center gap-3">
                                            <span className="font-mono text-xs font-bold text-white">{s.price} RON</span>
                                            <button onClick={() => handleSeatClick(s)} className="w-6 h-6 rounded-full bg-white/10 hover:bg-rose-500/30 text-white/70 hover:text-white text-xs flex items-center justify-center transition">✕</button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>

                    <div className="space-y-4 border-t border-white/10 pt-4">
                        <div className="flex justify-between text-base font-bold text-white">
                            <span className="text-white/70 font-medium">Total</span>
                            <span className="font-mono text-xl text-white">{totalAmount} RON</span>
                        </div>

                        <div className="grid grid-cols-2 gap-2">
                            <button type="button" onClick={() => setPaymentMethod('apple')} className={`px-3 py-2.5 rounded-2xl border text-xs font-semibold transition ${paymentMethod === 'apple' ? 'border-white/50 bg-white/20 text-white shadow-sm' : 'border-white/10 bg-white/5 text-white/60'}`}>
                                 Pay
                            </button>
                            <button type="button" onClick={() => setPaymentMethod('card')} className={`px-3 py-2.5 rounded-2xl border text-xs font-semibold transition ${paymentMethod === 'card' ? 'border-white/50 bg-white/20 text-white shadow-sm' : 'border-white/10 bg-white/5 text-white/60'}`}>
                                💳 Card
                            </button>
                        </div>

                        <button disabled={myLockedSeats.length === 0} onClick={handleCheckout} className={`w-full py-3.5 px-5 rounded-full font-bold text-sm transition-all ${myLockedSeats.length === 0 ? 'bg-white/10 text-white/30 cursor-not-allowed' : 'glass-pill-btn cursor-pointer'}`}>
                            {myLockedSeats.length === 0 ? 'Select Seats' : `Pay with ${paymentMethod === 'apple' ? 'Apple Pay' : 'Card'} • ${totalAmount} RON`}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default InteractiveSeating;
